command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
& git -C $repo fetch origin main --no-tags --prune
if($LASTEXITCODE -ne 0){throw "fetch main failed"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-classifier-permission-check-" + $env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try {
  & git -C $repo worktree add --detach $temp 6184dd124b48851e718586f2a9c2ada91824d984
  if($LASTEXITCODE -ne 0){throw "worktree add failed"}
  & python -X utf8 (Join-Path $temp "tests\winui\test_remote_failure_classifier.py")
  if($LASTEXITCODE -ne 0){throw "failure classifier tests failed"}
  & python -X utf8 (Join-Path $temp "tests\winui\test_remote_evidence_policy.py")
  if($LASTEXITCODE -ne 0){throw "remote evidence policy tests failed"}
  & python -X utf8 (Join-Path $temp "tests\winui\test_remote_windows_task_contract.py")
  if($LASTEXITCODE -ne 0){throw "remote workflow contract tests failed"}
  Write-Host "REMOTE_CLASSIFIER_PERMISSION_CHECK=PASS"
} finally {
  if(Test-Path -LiteralPath $temp){& git -C $repo worktree remove --force $temp}
  & git -C $repo worktree prune
}
